-- 303_ai_receptionist_follow_ups.sql — human-action tasks generated by the AI receptionist (spec: Follow-Ups). A
-- follow-up is created when the AI hands off to a callback (no live transfer available), or manually by staff. Every
-- row is tenant-owned and branch-scoped; it references the source call/appointment/customer where known. This is a
-- task queue, not a second customer/appointment store — it points at the existing records by id.

CREATE TABLE IF NOT EXISTS ai_receptionist_follow_ups (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          UUID NOT NULL,
  branch_id          UUID,
  reason             TEXT NOT NULL,                     -- CUSTOMER_REQUESTED_HUMAN | CALLBACK | COMPLAINT | ... (see core)
  priority           TEXT NOT NULL DEFAULT 'normal',    -- low | normal | high | urgent
  status             TEXT NOT NULL DEFAULT 'open',      -- open | assigned | in_progress | waiting | resolved | closed
  customer_id        UUID,
  caller_phone       TEXT,
  provider_call_id   TEXT,                              -- the source call (points at voice_call_outcomes.provider_call_id)
  appointment_id     UUID,
  assigned_user_id   UUID,
  due_at             TIMESTAMPTZ,
  notes              TEXT,
  resolution         TEXT,
  created_by_user_id UUID,                              -- NULL when created by the AI receptionist
  source             TEXT NOT NULL DEFAULT 'manual',    -- manual | ai_receptionist
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at        TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_air_followups_tenant_status ON ai_receptionist_follow_ups (tenant_id, status);
CREATE INDEX IF NOT EXISTS idx_air_followups_tenant_branch ON ai_receptionist_follow_ups (tenant_id, branch_id);
CREATE INDEX IF NOT EXISTS idx_air_followups_tenant_created ON ai_receptionist_follow_ups (tenant_id, created_at);
-- One open follow-up per source call, so a retried handoff never stacks duplicate callbacks (partial unique index).
CREATE UNIQUE INDEX IF NOT EXISTS uq_air_followup_open_call ON ai_receptionist_follow_ups (tenant_id, provider_call_id)
  WHERE provider_call_id IS NOT NULL AND status NOT IN ('resolved', 'closed');
